program.compute:
options = read('/input/options')
required = goal['cover']['tags']
result = []
for size in range(goal['min_count'], goal['max_count'] + 1):
    for group in combinations(options, size):
        ids = [item['id'] for item in group]
        tags = []
        for item in group:
            tags = tags + item['tags']
        cost = sum([item['cost'] for item in group])
        if all([tag in tags for tag in required]) and cost <= goal['sum_bounds']['cost']['max'] and valid(ids):
            result = ids
            break
    if len(result) > 0:
        break

program.effects:
if exists('/output/selection'):
    selection = read('/output/selection')
else:
    selection = result
    write('/output/selection', selection)
if receipt('report') == 'success':
    sent_state = 'sent'
elif receipt('report') == 'unknown':
    sent_state = status('report')
else:
    sent_state = 'not_sent'
if sent_state == 'not_sent':
    send('report', 'team', selection)
if exists('/tmp/cache'):
    delete('/tmp/cache')

